x": 133, "y": 264.5 }, "correction": { "x": 0, "y": 0 } } } }; const NS = "http://www.w3.org/2000/svg"; const noteState = { index: 0, instrument: "alto", timer: null, speed: 1, tween: 0, positions: new Map(), };
function svgEl(name, attrs = {}) { const el = document.createElementNS(NS, name); for (const [key, value] of Object.entries(attrs)) el.setAttribute(key, value); return el; }
function centerOf(key) { if (key.type === "circle") return { x: key.x, y: key.y }; return { x: key.x + key.w / 2, y: key.y + key.h / 2 }; }
function restPoint(key) { const center = centerOf(key); const side = center.x < 78 ? -18 : center.x > 124 ? 18 : 0; const vertical = center.y < 155 ? -30 : 30; return { x: center.x + side, y: center.y + vertical, scale: 0.82, opacity: 0.14 }; }
function pressPoint(key) { const center = centerOf(key); return { x: center.x, y: center.y + 1.6, scale: 1.06, opacity: 0.96 }; }
function pitchClassName(midi) { const names = ["C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab", "A", "Bb", "B"]; return names[((midi % 12) + 12) % 12] + (Math.floor(midi / 12) - 1); }
function setText(id, text) { const el = document.getElementById(id); if (el) el.textContent = text; }
function renderKeys() { const keyLayer = document.getElementById("anim-key-layer"); const fingerLayer = document.getElementById("anim-finger-layer"); keyLayer.replaceChildren(); fingerLayer.replaceChildren();
DATA.keys.forEach((key) => { const keyGroup = svgEl("g", { class: "anim-key", "data-key": key.id }); let shape; if (key.type === "circle") { shape = svgEl("circle", { cx: key.x, cy: key.y, r: key.r }); } else { shape = svgEl("rect", { x: key.x, y: key.y, width: key.w, height: key.h, rx: 7 }); } const labelX = key.type === "circle" ? key.x : key.x + key.w / 2; const labelY = key.type === "circle" ? key.y + 3 : key.y + key.h / 2 + 3; const label = svgEl("text", { x: labelX, y: labelY }); label.textContent = key.label; keyGroup.append(shape, label); keyLayer.append(keyGroup);
const center = centerOf(key); const rx = key.type === "circle" ? Math.max(key.r * 1.32, 8) : Math.max(key.w * 0.5, 10); const finger = svgEl("g", { class: "anim-finger", "data-key": key.id }); const pad = svgEl("ellipse", { cx: 0, cy: 0, rx, ry: Math.max(rx * 0.54, 7) }); const nail = svgEl("ellipse", { cx: rx * 0.16, cy: -1.5, rx: Math.max(rx * 0.28, 4), ry: 2.4, class: "finger-nail" }); finger.append(pad, nail); fingerLayer.append(finger); const start = restPoint(key); noteState.positions.set(key.id, start); finger.setAttribute("transform", "translate(" + start.x + " " + start.y + ") scale(" + start.scale + ")"); finger.style.opacity = start.opacity; }); }
function updateReadout(note) { const config = DATA.chartConfigs[noteState.instrument] || DATA.chartConfigs.alto; const concert = pitchClassName(note.midi - config.transpositionSemitones); setText("anim-instrument", config.englishName); setText("anim-note", note.label); setText("anim-concert", "실음 " + concert); setText("anim-formula", note.formula); setText("anim-active-count", note.pressed.length + " keys"); }
function setNote(nextIndex, animate = true) { noteState.index = (nextIndex + DATA.notes.length) % DATA.notes.length; const note = DATA.notes[noteState.index]; const pressed = new Set(note.pressed); updateReadout(note);
const noteSelect = document.getElementById("note-select"); if (noteSelect) noteSelect.value = String(noteState.index);
DATA.keys.forEach((key) => { const keyGroup = document.querySelector('.anim-key[data-key="' + key.id + '"]'); if (keyGroup) keyGroup.classList.toggle("active", pressed.has(key.id)); });
const tweenId = ++noteState.tween; const started = performance.now(); const duration = animate ? 430 : 1; const frames = DATA.keys.map((key) => { const from = noteState.positions.get(key.id) || restPoint(key); const to = pressed.has(key.id) ? pressPoint(key) : restPoint(key); return { key, from, to, el: document.querySelector('.anim-finger[data-key="' + key.id + '"]') }; });
function ease(t) { return 1 - Math.pow(1 - t, 3); }
function frame(now) { if (tweenId !== noteState.tween) return; const t = Math.min(1, (now - started) / duration); const e = ease(t); frames.forEach(({ key, from, to, el }) => { const x = from.x + (to.x - from.x) * e; const y = from.y + (to.y - from.y) * e; const scale = from.scale + (to.scale - from.scale) * e; const opacity = from.opacity + (to.opacity - from.opacity) * e; el.setAttribute("transform", "translate(" + x.toFixed(2) + " " + y.toFixed(2) + ") scale(" + scale.toFixed(3) + ")"); el.style.opacity = opacity.toFixed(3); if (t === 1) noteState.positions.set(key.id, to); }); if (t < 1) requestAnimationFrame(frame); }
requestAnimationFrame(frame); }
function stopPlayback() { if (noteState.timer) clearInterval(noteState.timer); noteState.timer = null; const playButton = document.getElementById("play-toggle"); if (playButton) playButton.textContent = "Play"; }
function playPlayback() { stopPlayback(); const playButton = document.getElementById("play-toggle"); if (playButton) playButton.textContent = "Pause"; const delay = Math.max(420, Math.round(1450 / noteState.speed)); noteState.timer = setInterval(() => setNote(noteState.index + 1), delay); }
function wireHtmlControls() { const instrumentSelect = document.getElementById("instrument-select"); const noteSelect = document.getElementById("note-select"); if (instrumentSelect) { instrumentSelect.replaceChildren(); Object.entries(DATA.chartConfigs).forEach(([id, config]) => { const option = document.createElement("option"); option.value = id; option.textContent = config.englishName.replace(" Saxophone", ""); instrumentSelect.append(option); }); instrumentSelect.value = noteState.instrument; instrumentSelect.addEventListener("change", () => { noteState.instrument = instrumentSelect.value; setNote(noteState.index, false); }); } if (noteSelect) { noteSelect.replaceChildren(); DATA.notes.forEach((note, index) => { const option = document.createElement("option"); option.value = String(index); option.textContent = note.label + " · " + note.short; noteSelect.append(option); }); noteSelect.addEventListener("change", () => setNote(Number(noteSelect.value))); } document.getElementById("prev-note")?.addEventListener("click", () => setNote(noteState.index - 1)); document.getElementById("next-note")?.addEventListener("click", () => setNote(noteState.index + 1)); document.getElementById("play-toggle")?.addEventListener("click", () => { if (noteState.timer) stopPlayback(); else playPlayback(); }); document.getElementById("speed-range")?.addEventListener("input", (event) => { noteState.speed = Number(event.target.value); if (noteState.timer) playPlayback(); }); }
window.initSaxAnimation = function initSaxAnimation(options = {}) { noteState.instrument = options.instrument || "alto"; noteState.speed = Number(document.getElementById("speed-range")?.value || 1); renderKeys(); wireHtmlControls(); setNote(0, false); if (options.standalone) { playPlayback(); document.getElementById("animation-stage")?.addEventListener("click", () => { if (noteState.timer) stopPlayback(); else playPlayback(); }); } }; })();
window.addEventListener("load", () => window.initSaxAnimation({ standalone: true }));
